import React from 'react';

import { CustomTooltip } from 'components/CustomTooltip';
import { Icon, Info } from 'components/icon';
import { Skeleton } from 'components/Skeleton';
import { StyledTitle } from 'shared/Styles';
import { createDataTestId } from 'utils/test/createDataTestId';

import {
  StyledInfoIconWrapper,
  StyledPageDescription,
  StyledPageTitleContainer,
  StyledPageTitleContent,
  StyledPageTitleRightContent,
  StyledPageTitleRow,
} from './PageTitle.styles';

export interface PageTitleProps {
  title: string;
  description?: string;
  tooltip?: React.ReactNode;
  tooltipIconSize?: 'large' | 'medium' | 'small';
  rightContent?: React.ReactNode;
  dataTestId?: string;
  isLoading?: boolean;
}

export const PageTitle: React.FC<PageTitleProps> = ({
  title,
  description,
  tooltip,
  tooltipIconSize = 'large',
  rightContent,
  dataTestId,
  isLoading = false,
}) => {
  return (
    <StyledPageTitleContainer data-testid={dataTestId}>
      <StyledPageTitleRow>
        <StyledPageTitleContent>
          {isLoading ? (
            <Skeleton
              width="360px"
              height="40px"
              length={1}
              borderRadius="large"
              dataTestId={createDataTestId(dataTestId, 'page-title-skeleton')}
            />
          ) : (
            <StyledTitle
              size="H2"
              data-testid={createDataTestId(dataTestId, 'page-title')}
            >
              {title}
            </StyledTitle>
          )}

          {!isLoading && tooltip && (
            <CustomTooltip
              content={tooltip}
              label={title}
              dataTestId={createDataTestId(dataTestId, 'page-title-tooltip')}
            >
              <StyledInfoIconWrapper size={tooltipIconSize}>
                <Icon
                  icon={Info}
                  data-testid={createDataTestId(
                    dataTestId,
                    'page-title-tooltip-icon',
                  )}
                />
              </StyledInfoIconWrapper>
            </CustomTooltip>
          )}
        </StyledPageTitleContent>

        {description &&
          (isLoading ? (
            <Skeleton
              width="480px"
              height="24px"
              length={1}
              borderRadius="large"
              dataTestId={createDataTestId(
                dataTestId,
                'page-title-description-skeleton',
              )}
            />
          ) : (
            <StyledPageDescription
              data-testid={createDataTestId(
                dataTestId,
                'page-title-description',
              )}
            >
              {description}
            </StyledPageDescription>
          ))}
      </StyledPageTitleRow>

      {rightContent && (
        <StyledPageTitleRightContent>
          {rightContent}
        </StyledPageTitleRightContent>
      )}
    </StyledPageTitleContainer>
  );
};
